343	        RfuVSync();
344	    else if (gLinkVSyncDisabled == FALSE)
345	        LinkVSync();
346	
347	    gMain.vblankCounter1++;
348	
349	    if (gTrainerHillVBlankCounter && *gTrainerHillVBlankCounter < 0xFFFFFFFF)
350	        (*gTrainerHillVBlankCounter)++;
351	
352	    if (gMain.vblankCallback)
353	        gMain.vblankCallback();
354	
355	    gMain.vblankCounter2++;
356	
357	    CopyBufferedValuesToGpuRegs();
358	    ProcessDma3Requests();
359	
360	    gPcmDmaCounter = gSoundInfo.pcmDmaCounter;
361	
362	    m4aSoundMain();
363	    TryReceiveLinkBattleData();
364	
365	    if (!gMain.inBattle || !(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_FRONTIER | BATTLE_TYPE_RECORDED)))
366	        Random();
367	
368	    UpdateWirelessStatusIndicatorSprite();
369	
370	    INTR_CHECK |= INTR_FLAG_VBLANK;
371	    gMain.intrCheck |= INTR_FLAG_VBLANK;
372	}
