   250	static void ReadKeys(void)
   251	{
   252	    u16 keyInput = REG_KEYINPUT ^ KEYS_MASK;
   253	    gMain.newKeysRaw = keyInput & ~gMain.heldKeysRaw;
   254	    gMain.newKeys = gMain.newKeysRaw;
   255	    gMain.newAndRepeatedKeys = gMain.newKeysRaw;
   256	
   257	    // BUG: Key repeat won't work when pressing L using L=A button mode
   258	    // because it compares the raw key input with the remapped held keys.
   259	    // Note that newAndRepeatedKeys is never remapped either.
   260	
   261	    if (keyInput != 0 && gMain.heldKeys == keyInput)
   262	    {
   263	        gMain.keyRepeatCounter--;
   264	
   265	        if (gMain.keyRepeatCounter == 0)
   266	        {
   267	            gMain.newAndRepeatedKeys = keyInput;
   268	            gMain.keyRepeatCounter = gKeyRepeatContinueDelay;
   269	        }
   270	    }
   271	    else
   272	    {
   273	        // If there is no input or the input has changed, reset the counter.
   274	        gMain.keyRepeatCounter = gKeyRepeatStartDelay;
   275	    }
   276	
   277	    gMain.heldKeysRaw = keyInput;
   278	    gMain.heldKeys = gMain.heldKeysRaw;
   279	
   280	    // Remap L to A if the L=A option is enabled.
   281	    if (gSaveBlock2Ptr->optionsButtonMode == OPTIONS_BUTTON_MODE_L_EQUALS_A)
   282	    {
   283	        if (JOY_NEW(L_BUTTON))
   284	            gMain.newKeys |= A_BUTTON;
   285	
   286	        if (JOY_HELD(L_BUTTON))
   287	            gMain.heldKeys |= A_BUTTON;
   288	    }
   289	
   290	    if (JOY_NEW(gMain.watchedKeysMask))
   291	        gMain.watchedKeysPressed = TRUE;
   292	}
