 233	static void HandleInputChooseAction(void)
 234	{
 235	    u16 itemId = gBattleBufferA[gActiveBattler][2] | (gBattleBufferA[gActiveBattler][3] << 8);
 236	
 237	    DoBounceEffect(gActiveBattler, BOUNCE_HEALTHBOX, 7, 1);
 238	    DoBounceEffect(gActiveBattler, BOUNCE_MON, 7, 1);
 239	
 240	    if (JOY_REPEAT(DPAD_ANY) && gSaveBlock2Ptr->optionsButtonMode == OPTIONS_BUTTON_MODE_L_EQUALS_A)
 241	        gPlayerDpadHoldFrames++;
 242	    else
 243	        gPlayerDpadHoldFrames = 0;
 244	
 245	    if (JOY_NEW(A_BUTTON))
 246	    {
 247	        PlaySE(SE_SELECT);
 248	
 249	        switch (gActionSelectionCursor[gActiveBattler])
 250	        {
 251	        case 0: // Top left
 252	            BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, B_ACTION_USE_MOVE, 0);
 253	            break;
 254	        case 1: // Top right
 255	            BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, B_ACTION_USE_ITEM, 0);
 256	            break;
 257	        case 2: // Bottom left
 258	            BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, B_ACTION_SWITCH, 0);
 259	            break;
 260	        case 3: // Bottom right
 261	            BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, B_ACTION_RUN, 0);
 262	            break;
 263	        }
 264	        PlayerBufferExecCompleted();
 265	    }
 266	    else if (JOY_NEW(DPAD_LEFT))
 267	    {
 268	        if (gActionSelectionCursor[gActiveBattler] & 1) // if is B_ACTION_USE_ITEM or B_ACTION_RUN
 269	        {
 270	            PlaySE(SE_SELECT);
 271	            ActionSelectionDestroyCursorAt(gActionSelectionCursor[gActiveBattler]);
 272	            gActionSelectionCursor[gActiveBattler] ^= 1;
 273	            ActionSelectionCreateCursorAt(gActionSelectionCursor[gActiveBattler], 0);
 274	        }
 275	    }
 276	    else if (JOY_NEW(DPAD_RIGHT))
 277	    {
 278	        if (!(gActionSelectionCursor[gActiveBattler] & 1)) // if is B_ACTION_USE_MOVE or B_ACTION_SWITCH
 279	        {
 280	            PlaySE(SE_SELECT);
 281	            ActionSelectionDestroyCursorAt(gActionSelectionCursor[gActiveBattler]);
 282	            gActionSelectionCursor[gActiveBattler] ^= 1;
 283	            ActionSelectionCreateCursorAt(gActionSelectionCursor[gActiveBattler], 0);
 284	        }
 285	    }
 286	    else if (JOY_NEW(DPAD_UP))
 287	    {
 288	        if (gActionSelectionCursor[gActiveBattler] & 2) // if is B_ACTION_SWITCH or B_ACTION_RUN
 289	        {
 290	            PlaySE(SE_SELECT);
 291	            ActionSelectionDestroyCursorAt(gActionSelectionCursor[gActiveBattler]);
 292	            gActionSelectionCursor[gActiveBattler] ^= 2;
 293	            ActionSelectionCreateCursorAt(gActionSelectionCursor[gActiveBattler], 0);
 294	        }
 295	    }
 296	    else if (JOY_NEW(DPAD_DOWN))
 297	    {
 298	        if (!(gActionSelectionCursor[gActiveBattler] & 2)) // if is B_ACTION_USE_MOVE or B_ACTION_USE_ITEM
 299	        {
 300	            PlaySE(SE_SELECT);
 301	            ActionSelectionDestroyCursorAt(gActionSelectionCursor[gActiveBattler]);
 302	            gActionSelectionCursor[gActiveBattler] ^= 2;
 303	            ActionSelectionCreateCursorAt(gActionSelectionCursor[gActiveBattler], 0);
 304	        }
 305	    }
 306	    else if (JOY_NEW(B_BUTTON) || gPlayerDpadHoldFrames > 59)
 307	    {
 308	        if ((gBattleTypeFlags & BATTLE_TYPE_DOUBLE)
 309	         && GetBattlerPosition(gActiveBattler) == B_POSITION_PLAYER_RIGHT
 310	         && !(gAbsentBattlerFlags & gBitTable[GetBattlerAtPosition(B_POSITION_PLAYER_LEFT)])
 311	         && !(gBattleTypeFlags & BATTLE_TYPE_MULTI))
 312	        {
 313	            if (gBattleBufferA[gActiveBattler][1] == B_ACTION_USE_ITEM)
 314	            {
 315	                // Add item to bag if it is a ball
 316	                if (itemId <= LAST_BALL)
 317	                    AddBagItem(itemId, 1);
 318	                else
 319	                    return;
 320	            }
 321	            PlaySE(SE_SELECT);
 322	            BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, B_ACTION_CANCEL_PARTNER, 0);
 323	            PlayerBufferExecCompleted();
 324	        }
 325	    }
 326	    else if (JOY_NEW(START_BUTTON))
 327	    {
 328	        SwapHpBarsWithHpText();
 329	    }
 330	}
