 474	    struct ChooseMoveStruct *moveInfo = (struct ChooseMoveStruct *)(&gBattleBufferA[gActiveBattler][4]);
 475	
 476	    if (JOY_HELD(DPAD_ANY) && gSaveBlock2Ptr->optionsButtonMode == OPTIONS_BUTTON_MODE_L_EQUALS_A)
 477	        gPlayerDpadHoldFrames++;
 478	    else
 479	        gPlayerDpadHoldFrames = 0;
 480	
 481	    if (JOY_NEW(A_BUTTON))
 482	    {
 483	        u8 moveTarget;
 484	
 485	        PlaySE(SE_SELECT);
 486	        if (moveInfo->moves[gMoveSelectionCursor[gActiveBattler]] == MOVE_CURSE)
 487	        {
 488	            if (moveInfo->monTypes[0] != TYPE_GHOST && moveInfo->monTypes[1] != TYPE_GHOST)
 489	                moveTarget = MOVE_TARGET_USER;
 490	            else
 491	                moveTarget = MOVE_TARGET_SELECTED;
 492	        }
 493	        else
 494	        {
 495	            moveTarget = gBattleMoves[moveInfo->moves[gMoveSelectionCursor[gActiveBattler]]].target;
 496	        }
 497	
 498	        if (moveTarget & MOVE_TARGET_USER)
 499	            gMultiUsePlayerCursor = gActiveBattler;
 500	        else
 501	            gMultiUsePlayerCursor = GetBattlerAtPosition(BATTLE_OPPOSITE(GET_BATTLER_SIDE(gActiveBattler)));
 502	
 503	        if (!gBattleBufferA[gActiveBattler][1]) // not a double battle
 504	        {
 505	            if (moveTarget & MOVE_TARGET_USER_OR_SELECTED && !gBattleBufferA[gActiveBattler][2])
 506	                canSelectTarget++;
 507	        }
 508	        else // double battle
 509	        {
 510	            if (!(moveTarget & (MOVE_TARGET_RANDOM | MOVE_TARGET_BOTH | MOVE_TARGET_DEPENDS | MOVE_TARGET_FOES_AND_ALLY | MOVE_TARGET_OPPONENTS_FIELD | MOVE_TARGET_USER)))
 511	                canSelectTarget++; // either selected or user
 512	
 513	            if (moveInfo->currentPP[gMoveSelectionCursor[gActiveBattler]] == 0)
 514	            {
 515	                canSelectTarget = FALSE;
 516	            }
 517	            else if (!(moveTarget & (MOVE_TARGET_USER | MOVE_TARGET_USER_OR_SELECTED)) && CountAliveMonsInBattle(BATTLE_ALIVE_EXCEPT_ACTIVE) <= 1)
 518	            {
 519	                gMultiUsePlayerCursor = GetDefaultMoveTarget(gActiveBattler);
 520	                canSelectTarget = FALSE;
 521	            }
 522	        }
 523	
 524	        if (!canSelectTarget)
 525	        {
 526	            BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, B_ACTION_EXEC_SCRIPT, gMoveSelectionCursor[gActiveBattler] | (gMultiUsePlayerCursor << 8));
 527	            PlayerBufferExecCompleted();
 528	        }
 529	        else
 530	        {
 531	            gBattlerControllerFuncs[gActiveBattler] = HandleInputChooseTarget;
 532	
 533	            if (moveTarget & (MOVE_TARGET_USER | MOVE_TARGET_USER_OR_SELECTED))
 534	                gMultiUsePlayerCursor = gActiveBattler;
 535	            else if (gAbsentBattlerFlags & gBitTable[GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT)])
 536	                gMultiUsePlayerCursor = GetBattlerAtPosition(B_POSITION_OPPONENT_RIGHT);
 537	            else
 538	                gMultiUsePlayerCursor = GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT);
 539	
 540	            gSprites[gBattlerSpriteIds[gMultiUsePlayerCursor]].callback = SpriteCB_ShowAsMoveTarget;
 541	        }
 542	    }
 543	    else if (JOY_NEW(B_BUTTON) || gPlayerDpadHoldFrames > 59)
 544	    {
 545	        PlaySE(SE_SELECT);
 546	        BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, B_ACTION_EXEC_SCRIPT, 0xFFFF);
 547	        PlayerBufferExecCompleted();
 548	    }
 549	    else if (JOY_NEW(DPAD_LEFT))
 550	    {
 551	        if (gMoveSelectionCursor[gActiveBattler] & 1)
 552	        {
 553	            MoveSelectionDestroyCursorAt(gMoveSelectionCursor[gActiveBattler]);
 554	            gMoveSelectionCursor[gActiveBattler] ^= 1;
 555	            PlaySE(SE_SELECT);
 556	            MoveSelectionCreateCursorAt(gMoveSelectionCursor[gActiveBattler], 0);
 557	            MoveSelectionDisplayPPNumber();
 558	            MoveSelectionDisplayMoveType();
 559	        }
 560	    }
 561	    else if (JOY_NEW(DPAD_RIGHT))
 562	    {
 563	        if (!(gMoveSelectionCursor[gActiveBattler] & 1)
 564	         && (gMoveSelectionCursor[gActiveBattler] ^ 1) < gNumberOfMovesToChoose)
 565	        {
 566	            MoveSelectionDestroyCursorAt(gMoveSelectionCursor[gActiveBattler]);
 567	            gMoveSelectionCursor[gActiveBattler] ^= 1;
 568	            PlaySE(SE_SELECT);
 569	            MoveSelectionCreateCursorAt(gMoveSelectionCursor[gActiveBattler], 0);
 570	            MoveSelectionDisplayPPNumber();
 571	            MoveSelectionDisplayMoveType();
 572	        }
 573	    }
 574	    else if (JOY_NEW(DPAD_UP))
 575	    {
 576	        if (gMoveSelectionCursor[gActiveBattler] & 2)
 577	        {
 578	            MoveSelectionDestroyCursorAt(gMoveSelectionCursor[gActiveBattler]);
 579	            gMoveSelectionCursor[gActiveBattler] ^= 2;
 580	            PlaySE(SE_SELECT);
 581	            MoveSelectionCreateCursorAt(gMoveSelectionCursor[gActiveBattler], 0);
 582	            MoveSelectionDisplayPPNumber();
 583	            MoveSelectionDisplayMoveType();
 584	        }
 585	    }
 586	    else if (JOY_NEW(DPAD_DOWN))
 587	    {
 588	        if (!(gMoveSelectionCursor[gActiveBattler] & 2)
 589	         && (gMoveSelectionCursor[gActiveBattler] ^ 2) < gNumberOfMovesToChoose)
 590	        {
 591	            MoveSelectionDestroyCursorAt(gMoveSelectionCursor[gActiveBattler]);
 592	            gMoveSelectionCursor[gActiveBattler] ^= 2;
 593	            PlaySE(SE_SELECT);
 594	            MoveSelectionCreateCursorAt(gMoveSelectionCursor[gActiveBattler], 0);
 595	            MoveSelectionDisplayPPNumber();
 596	            MoveSelectionDisplayMoveType();
 597	        }
 598	    }
 599	    else if (JOY_NEW(SELECT_BUTTON))
 600	    {
 601	        if (gNumberOfMovesToChoose > 1 && !(gBattleTypeFlags & BATTLE_TYPE_LINK))
 602	        {
 603	            MoveSelectionCreateCursorAt(gMoveSelectionCursor[gActiveBattler], 29);
 604	
 605	            if (gMoveSelectionCursor[gActiveBattler] != 0)
 606	                gMultiUsePlayerCursor = 0;
 607	            else
 608	                gMultiUsePlayerCursor = gMoveSelectionCursor[gActiveBattler] + 1;
 609	
 610	            MoveSelectionCreateCursorAt(gMultiUsePlayerCursor, 27);
 611	            BattlePutTextOnWindow(gText_BattleSwitchWhich, B_WIN_SWITCH_PROMPT);
