4129	static void HandleTurnActionSelectionState(void)
4130	{
4131	    s32 i;
4132	
4133	    gBattleCommunication[ACTIONS_CONFIRMED_COUNT] = 0;
4134	    for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
4135	    {
4136	        u8 position = GetBattlerPosition(gActiveBattler);
4137	        switch (gBattleCommunication[gActiveBattler])
4138	        {
4139	        case STATE_TURN_START_RECORD: // Recorded battle related action on start of every turn.
4140	            RecordedBattle_CopyBattlerMoves();
4141	            gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
4142	            break;
4143	        case STATE_BEFORE_ACTION_CHOSEN: // Choose an action.
4144	            *(gBattleStruct->monToSwitchIntoId + gActiveBattler) = PARTY_SIZE;
4145	            if (gBattleTypeFlags & BATTLE_TYPE_MULTI
4146	                || (position & BIT_FLANK) == B_FLANK_LEFT
4147	                || gBattleStruct->absentBattlerFlags & gBitTable[GetBattlerAtPosition(BATTLE_PARTNER(position))]
4148	                || gBattleCommunication[GetBattlerAtPosition(BATTLE_PARTNER(position))] == STATE_WAIT_ACTION_CONFIRMED)
4149	            {
4150	                if (gBattleStruct->absentBattlerFlags & gBitTable[gActiveBattler])
4151	                {
4152	                    gChosenActionByBattler[gActiveBattler] = B_ACTION_NOTHING_FAINTED;
4153	                    if (!(gBattleTypeFlags & BATTLE_TYPE_MULTI))
4154	                        gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED;
4155	                    else
4156	                        gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
4157	                }
4158	                else
4159	                {
4160	                    if (gBattleMons[gActiveBattler].status2 & STATUS2_MULTIPLETURNS
4161	                        || gBattleMons[gActiveBattler].status2 & STATUS2_RECHARGE)
4162	                    {
4163	                        gChosenActionByBattler[gActiveBattler] = B_ACTION_USE_MOVE;
4164	                        gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
4165	                    }
4166	                    else
4167	                    {
4168	                        BtlController_EmitChooseAction(B_COMM_TO_CONTROLLER, gChosenActionByBattler[0], gBattleBufferB[0][1] | (gBattleBufferB[0][2] << 8));
4169	                        MarkBattlerForControllerExec(gActiveBattler);
4170	                        gBattleCommunication[gActiveBattler]++;
4171	                    }
4172	                }
4173	            }
4174	            break;
4175	        case STATE_WAIT_ACTION_CHOSEN: // Try to perform an action.
4176	            if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
4177	            {
4178	                RecordedBattle_SetBattlerAction(gActiveBattler, gBattleBufferB[gActiveBattler][1]);
4179	                gChosenActionByBattler[gActiveBattler] = gBattleBufferB[gActiveBattler][1];
4180	
4181	                switch (gBattleBufferB[gActiveBattler][1])
4182	                {
4183	                case B_ACTION_USE_MOVE:
4184	                    if (AreAllMovesUnusable())
4185	                    {
4186	                        gBattleCommunication[gActiveBattler] = STATE_SELECTION_SCRIPT;
4187	                        *(gBattleStruct->selectionScriptFinished + gActiveBattler) = FALSE;
4188	                        *(gBattleStruct->stateIdAfterSelScript + gActiveBattler) = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
4189	                        *(gBattleStruct->moveTarget + gActiveBattler) = gBattleBufferB[gActiveBattler][3];
4190	                        return;
4191	                    }
4192	                    else if (gDisableStructs[gActiveBattler].encoredMove != 0)
4193	                    {
4194	                        gChosenMoveByBattler[gActiveBattler] = gDisableStructs[gActiveBattler].encoredMove;
4195	                        *(gBattleStruct->chosenMovePositions + gActiveBattler) = gDisableStructs[gActiveBattler].encoredMovePos;
4196	                        gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
4197	                        return;
4198	                    }
4199	                    else
4200	                    {
4201	                        struct ChooseMoveStruct moveInfo;
4202	
4203	                        moveInfo.species = gBattleMons[gActiveBattler].species;
4204	                        moveInfo.monTypes[0] = gBattleMons[gActiveBattler].types[0];
4205	                        moveInfo.monTypes[1] = gBattleMons[gActiveBattler].types[1];
4206	
4207	                        for (i = 0; i < MAX_MON_MOVES; i++)
4208	                        {
4209	                            moveInfo.moves[i] = gBattleMons[gActiveBattler].moves[i];
4210	                            moveInfo.currentPP[i] = gBattleMons[gActiveBattler].pp[i];
4211	                            moveInfo.maxPP[i] = CalculatePPWithBonus(
4212	                                                            gBattleMons[gActiveBattler].moves[i],
4213	                                                            gBattleMons[gActiveBattler].ppBonuses,
4214	                                                            i);
4215	                        }
4216	
4217	                        BtlController_EmitChooseMove(B_COMM_TO_CONTROLLER, (gBattleTypeFlags & BATTLE_TYPE_DOUBLE) != 0, FALSE, &moveInfo);
4218	                        MarkBattlerForControllerExec(gActiveBattler);
4219	                    }
4220	                    break;
4221	                case B_ACTION_USE_ITEM:
4222	                    if (gBattleTypeFlags & (BATTLE_TYPE_LINK
